import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class ProblemE {
    public static long M = 998244353L;

    public static void main(String[] args) throws Exception {
        long[] v = new BufferedReader(new InputStreamReader(System.in)).lines()
                .flatMap(line -> Arrays.stream(line.trim().split("\\s+")))
                .filter(w -> !w.isEmpty())
                .mapToLong(Long::parseLong)
                .limit(4)
                .toArray();

        long m = v[0];
        long n = v[1];
        long l = v[2];
        long r = v[3];

        long T = m * n;
        long num = r - l + 1;
        long a = exp(num, T);
        long inv2 = 499122177L;

        if (T % 2 == 1) {
            System.out.println(a);
        } else if (num % 2 == 0) {
            System.out.println((a * inv2) % M);
        } else {
            System.out.println(((a + 1) % M * inv2) % M);
        }
    }

    public static long exp(long a, long b) {
        if (b == 0) return 1;
        if (b == 1) return a;
        long[] stack = new long[64];
        int size = 0;
        while (b != 0 && b != 1) {
            if (b % 2 != 0) {
                stack[size++] = a;
            }
            a = (a * a) % M;
            b /= 2;
        }
        long ans = (b == 1) ? a : 1;
        while (size > 0) {
            ans = (ans * stack[--size]) % M;
        }
        return ans;
    }
}
